-- Nội thất LOD 3 Tòa A (sinh bởi Models_3D/scripts/07_import_lod3.py, nạp sau 02)
-- Dữ liệu số hóa từ model 3D + sơ đồ tầng/danh bạ phòng công khai, cần kiểm chứng thực địa
BEGIN;
DELETE FROM rooms WHERE building_id = (SELECT id FROM buildings WHERE building_code = 'A');
DELETE FROM floors WHERE building_id = (SELECT id FROM buildings WHERE building_code = 'A');
COMMIT;
